<?php\ndeclare(strict_types=1);\n\nabstract class AbstractStateMachine\n{\n    protected string $currentState;\n    protected array $transitions = [];\n\n    public function canTransition(string $toState): bool\n    {\n        return isset($this->transitions[$this->currentState])\n            && in_array($toState, $this->transitions[$this->currentState]);\n    }\n\n    public function transition(string $toState): bool\n    {\n        if (!$this->canTransition($toState)) {\n            throw new \InvalidOperationException(\n                'Invalid transition from ' . $this->currentState . ' to ' . $toState\n            );\n        }\n        $this->currentState = $toState;\n        $this->onTransition($toState);\n        return true;\n    }\n\n    protected function onTransition(string $toState): void\n    {\n        // Hook for subclasses\n    }\n}\n